public int singleNumber(int[] nums) {
    Set<Integer> seen = new HashSet<>();
    for (int x : nums) {
        if (!seen.add(x)) {
            seen.remove(x);
        }
    }
    return seen.iterator().next();
}

code.python:
def singleNumber(self, nums: list[int]) -> int:
    seen: set[int] = set()
    for x in nums:
        if x in seen:
            seen.remove(x)
        else:
            seen.add(x)
    return seen.pop()

